"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["81144"],{48688(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.fato_elegibilidade_da_isencao","status":422,"titulo":"O fato que decide quem recebe o acr\xe9scimo depende do que s\xf3 a isen\xe7\xe3o coleta"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.fato_elegibilidade_da_isencao","requisitos":[],"oQueAconteceu":["O processo aplica o Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (o acr\xe9scimo\\nna nota) e escolheu um fato booleano para decidir quem o recebe. Esse fato\\ndepende, diretamente ou pelos fatos de que \xe9 calculado, de uma resposta que s\xf3 o\\nformul\xe1rio de isen\xe7\xe3o da taxa coleta.","O acr\xe9scimo \xe9 decidido na inscri\xe7\xe3o, e o sistema precisa resolver o fato\\nescolhido para todo candidato. Uma resposta que s\xf3 o formul\xe1rio de isen\xe7\xe3o\\ncoleta n\xe3o \xe9 conhecida na inscri\xe7\xe3o, e por isso n\xe3o pode decidir o acr\xe9scimo.","A confer\xeancia s\xf3 acontece quando o formul\xe1rio de inscri\xe7\xe3o j\xe1 declara a fase em\\nque \xe9 respondido. Antes disso, a pend\xeancia que aparece \xe9 a do pr\xf3prio\\nformul\xe1rio (`uniplus.selecao.processo_seletivo.formulario_sem_fase`). A\\npublica\xe7\xe3o ou a retifica\xe7\xe3o recusadas por esta causa n\xe3o congelam nenhuma\\nvers\xe3o."],"comoResolver":["Escolha, no Fator de Atenua\xe7\xe3o do processo, um fato que o formul\xe1rio de\\ninscri\xe7\xe3o pergunta ou que o processo deriva apenas de respostas da inscri\xe7\xe3o.\\nSe o fato escolhido \xe9 calculado por uma regra de deriva\xe7\xe3o do processo, ajuste a\\nregra para que ela n\xe3o dependa de resposta do formul\xe1rio de isen\xe7\xe3o.","Em processo j\xe1 publicado, fa\xe7a a troca numa retifica\xe7\xe3o e repita a opera\xe7\xe3o\\nrecusada."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);